/** Footnotes shown under the shortcut lists. */
export const KEY_NOTES = ["`Ctrl` works wherever `Cmd` is listed."];

/** The search bar's key hint line, per search state. */
export const SEARCH_BAR_HINTS = {
  closed: "o / search",
  open: "Tab history · ^u clear · ↵ open · ⌘↵ new tab · Esc↵ bookmark",
  openNoHistory: "^u clear · ↵ open · ⌘↵ new tab · Esc↵ bookmark",
};

/** Splits "`f` / `F`" into [{kbd: true, text: "f"}, {kbd: false, text: " / "}, ...]. */
export function parseKeyText(text) {
  return text
    .split("`")
    .map((part, i) => ({ kbd: i % 2 === 1, text: part }))
    .filter((part) => part.text);
}

/** All entries' `field` items (status or ticker), in order. */
export function collect(field) {
  return KEY_SECTIONS.flatMap((section) => section.entries.flatMap((entry) => entry[field] || []));
}

/** README's generated "Keys" section body (Markdown). */
export function keysMarkdown() {
  const lines = [];
  for (const section of KEY_SECTIONS) {
    lines.push(`### ${section.title}`, "", "| Key | Action |", "| --- | --- |");
    for (const entry of section.entries) lines.push(`| ${entry.keys} | ${entry.summary} |`);
    lines.push("");
  }
  lines.push(...KEY_NOTES);
  return lines.join("\n");
}
